import{_ as t,C as r,o as n,c as l,a3 as s,b as o,w as e,a as p,E as u,a4 as d}from"./chunks/framework.BvvarXmc.js";const m="/screenshots/presensi.png",P=JSON.parse('{"title":"Pencatatan Presensi Harian Siswa","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-guru/presensi-siswa.md","filePath":"panduan-guru/presensi-siswa.md","lastUpdated":null}'),g={name:"panduan-guru/presensi-siswa.md"};function h(k,a,c,_,w,b){const i=r("Mermaid");return n(),l("div",null,[a[1]||(a[1]=s('<h1 id="pencatatan-presensi-harian-siswa" tabindex="-1">Pencatatan Presensi Harian Siswa <a class="header-anchor" href="#pencatatan-presensi-harian-siswa" aria-label="Permalink to &quot;Pencatatan Presensi Harian Siswa&quot;">​</a></h1><p>Guru atau Wali Kelas dapat melakukan pencatatan kehadiran siswa secara digital langsung dari laptop maupun smartphone tanpa perlu buku absen kertas.</p><hr><h2 id="tampilan-halaman-presensi-siswa" tabindex="-1">Tampilan Halaman Presensi Siswa <a class="header-anchor" href="#tampilan-halaman-presensi-siswa" aria-label="Permalink to &quot;Tampilan Halaman Presensi Siswa&quot;">​</a></h2><p><img src="'+m+'" alt="Presensi Siswa"></p><hr><h2 id="langkah-pengisian-absensi-kelas" tabindex="-1">Langkah Pengisian Absensi Kelas <a class="header-anchor" href="#langkah-pengisian-absensi-kelas" aria-label="Permalink to &quot;Langkah Pengisian Absensi Kelas&quot;">​</a></h2>',7)),(n(),o(d,null,{default:e(()=>[u(i,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Pilih%20Kelas%20%26%20Tanggal%22%5D%20--%3E%20B%5B%222.%20Periksa%20Daftar%20Siswa%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Tandai%20S%20%2F%20I%20%2F%20A%20%2F%20T%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Klik%20'Simpan%20Presensi'%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Rekap%20Kehadiran%20Terupdate%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<h3 id="langkah-langkah" tabindex="-1">Langkah-langkah: <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah:&quot;">​</a></h3><ol><li>Buka menu <strong>Manajemen Absensi</strong> <strong>Absensi Siswa</strong>.</li><li>Pilih <strong>Kelas</strong> yang sedang Anda ajar (misal: <em>Kelas 7 - AL FUQON</em>).</li><li>Tentukan tanggal presensi (default: hari ini).</li><li>Layar menampilkan seluruh siswa di kelas tersebut: <ul><li>Secara default, seluruh siswa tercentang <strong>Hadir (H)</strong>.</li></ul></li><li>Anda cukup menandai siswa yang berhalangan: <ul><li><strong>S (Sakit)</strong>: Siswa sakit (bisa lampirkan foto surat dokter).</li><li><strong>I (Izin)</strong>: Siswa mengajukan izin resmi keluarga.</li><li><strong>A (Alfa)</strong>: Siswa tidak hadir tanpa kabar.</li><li><strong>T (Terlambat)</strong>: Siswa hadir melewati jam bel masuk.</li></ul></li><li>Klik tombol <strong><code>Simpan Presensi</code></strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Mesin Fingerprint &amp; Tap Kartu RFID</p><p>Jika sekolah menggunakan gerbang mesin tap RFID atau sidik jari di pintu masuk, jam kedatangan dan jam pulang siswa otomatis tercatat secara realtime di halaman ini tanpa perlu input manual.</p></div>',3))])}const T=t(g,[["render",h]]);export{P as __pageData,T as default};
